function TROP_BIRTH_SUM(points P[0..n-1], distance d):
    D <- -infinity                      # tropical additive identity (zero)
    for i from 0 to n-1:
        for j from i+1 to n-1:
            D <- max(D, d(P[i], P[j]))  # tropical addition  a (+) b = max(a,b)
    return D                            # = diameter = least completion scale

function IS_COMPLETE_AT(points P, distance d, scale eps):
    for i from 0 to n-1:
        for j from i+1 to n-1:
            if d(P[i], P[j]) > eps:
                return False            # witnessing unfilled pair {i,j}
    return True                          # every edge present => full complex

function FACE_BIRTH(face s, distance d):
    if |s| < 2: return -infinity
    return max over distinct x,y in s of d(x, y)

function SKELETON_COMPLETION_SCALES(points P, distance d, kmax):
    out <- empty list
    for k from 1 to kmax:
        scale <- -infinity
        for each (k+1)-subset s of P:
            scale <- max(scale, FACE_BIRTH(s, d))
        append scale to out
    return out

